import { test } from "node:test";
import assert from "node:assert/strict";
import {
	formatListDate,
	formatDetailDate,
	formatShortDate,
	formatQuotedDate,
} from "../../shared/dates.ts";

const time = (d: Date) =>
	d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });

test("invalid dates are returned unchanged", () => {
	for (const fn of [formatListDate, formatDetailDate, formatShortDate, formatQuotedDate]) {
		assert.equal(fn("not a date"), "not a date");
		assert.equal(fn(""), "");
	}
});

test("formatQuotedDate returns empty string for undefined", () => {
	assert.equal(formatQuotedDate(undefined), "");
});

test("formatQuotedDate is deterministic en-US format", () => {
	// Local-time input so the result is timezone independent.
	assert.equal(
		formatQuotedDate("2026-04-14T15:42:00"),
		"Tue, Apr 14, 2026 at 3:42 PM".replace(" at", ",").replace("2026,", "2026,"),
	);
});

test("formatShortDate shows time only", () => {
	const d = new Date(2024, 3, 15, 15, 42);
	assert.equal(formatShortDate(d.toISOString()), time(d));
});

test("formatDetailDate includes weekday, month, day and time", () => {
	const d = new Date(2024, 3, 15, 15, 42);
	const out = formatDetailDate(d.toISOString());
	assert.equal(
		out,
		d.toLocaleDateString(undefined, {
			weekday: "short",
			month: "short",
			day: "numeric",
			hour: "numeric",
			minute: "2-digit",
		}),
	);
	assert.match(out, /Apr/);
	assert.match(out, /15/);
});

test("formatListDate: today shows time only", () => {
	const now = new Date();
	const d = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 1);
	assert.equal(formatListDate(d.toISOString()), time(d));
});

test("formatListDate: earlier this year omits the year", () => {
	const now = new Date();
	// Jan 1 of this year at noon; skip if that is today.
	const d = new Date(now.getFullYear(), 0, 1, 12, 0);
	if (d.toDateString() === now.toDateString()) return;
	const out = formatListDate(d.toISOString());
	assert.equal(out, d.toLocaleDateString(undefined, { month: "short", day: "numeric" }));
	assert.ok(!out.includes(String(now.getFullYear())));
});

test("formatListDate: previous years include the year", () => {
	const d = new Date(2020, 3, 15, 12, 0);
	const out = formatListDate(d.toISOString());
	assert.equal(
		out,
		d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" }),
	);
	assert.match(out, /2020/);
});
