import { test } from "node:test";
import assert from "node:assert/strict";
import {
	Folders,
	SYSTEM_FOLDER_IDS,
	FOLDER_DISPLAY_NAMES,
	FOLDER_TOOL_DESCRIPTION,
	MOVE_FOLDER_TOOL_DESCRIPTION,
	getFolderDisplayName,
} from "../../shared/folders.ts";

test("Folders has the canonical ids", () => {
	assert.deepEqual(Folders, {
		INBOX: "inbox",
		SENT: "sent",
		DRAFT: "draft",
		ARCHIVE: "archive",
		TRASH: "trash",
		SPAM: "spam",
	});
});

test("SYSTEM_FOLDER_IDS is ordered and excludes spam", () => {
	assert.deepEqual([...SYSTEM_FOLDER_IDS], ["inbox", "sent", "draft", "archive", "trash"]);
	assert.ok(!SYSTEM_FOLDER_IDS.includes(Folders.SPAM));
});

test("every folder has a display name", () => {
	for (const id of Object.values(Folders)) {
		assert.ok(FOLDER_DISPLAY_NAMES[id], `missing name for ${id}`);
	}
	assert.equal(FOLDER_DISPLAY_NAMES[Folders.DRAFT], "Drafts");
});

test("tool descriptions list every system folder", () => {
	for (const id of SYSTEM_FOLDER_IDS) {
		assert.ok(FOLDER_TOOL_DESCRIPTION.includes(id));
		assert.ok(MOVE_FOLDER_TOOL_DESCRIPTION.includes(id));
	}
	assert.ok(!FOLDER_TOOL_DESCRIPTION.includes("spam"));
});

test("getFolderDisplayName: known ids, case-insensitive", () => {
	assert.equal(getFolderDisplayName("inbox"), "Inbox");
	assert.equal(getFolderDisplayName("INBOX"), "Inbox");
	assert.equal(getFolderDisplayName("Draft"), "Drafts");
	assert.equal(getFolderDisplayName("spam"), "Spam");
});

test("getFolderDisplayName: unknown ids get capitalised first letter, case preserved", () => {
	assert.equal(getFolderDisplayName("custom"), "Custom");
	assert.equal(getFolderDisplayName("myFolder"), "MyFolder");
});

test("getFolderDisplayName: empty string yields empty string", () => {
	assert.equal(getFolderDisplayName(""), "");
});
